/* @lc app=leetcode id=2867 lang=kotlin */
class Solution { fun countPaths(n: Int, edges: Array<IntArray>): Long = BooleanArray(n + 1) { it < 2 }.apply { (2..n).takeWhile { it * it <= n }.forEach { i -> if (!this[i]) (i * i..n step i).forEach { j -> this[j] = true } } }.let { notPrime -> Array(n + 1) { mutableListOf<Int>() }.apply { edges.forEach { e -> this[e[0]].add(e[1]).also { this[e[1]].add(e[0]) } } }.let { adj -> longArrayOf(0L).let { ans -> DeepRecursiveFunction<Pair<Int, Int>, LongArray> { (u, p) -> (if (notPrime[u]) longArrayOf(1, 0) else longArrayOf(0, 1)).also { res -> adj[u].filter { it != p }.forEach { v -> callRecursive(v to u).also { child -> (child[0] * res[1] + child[1] * res[0]).let { ans[0] += it }.run { if (notPrime[u]) res.apply { res[0] += child[0] }.apply { res[1] += child[1] } else res.apply { res[1] += child[0] } } } } } }.callRecursive(1 to -1).run { ans[0] } } } } }